import { readFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import path from "node:path";
import { emitModels, writeGenerated } from "./lib/contract-codegen.mjs";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const contract = JSON.parse(
  await readFile(path.join(root, "contracts/organization-identity.json"), "utf8"),
);
const models = emitModels(contract.models);
await writeGenerated(
  root,
  "backend/pkg/organizationidentity/types.go",
  '// Code generated by scripts/generate-organization-identity.mjs; DO NOT EDIT.\npackage organizationidentity\n\nimport ("time"; "github.com/google/uuid")\n\n' +
    models.go,
  "packages/api/src/organization-identity-contract.ts",
  '// Generated by scripts/generate-organization-identity.mjs.\nimport { z } from "zod";\n\n' +
    models.ts,
  "organisation identity",
);
